package com.acme.reporting;

import javax.inject.Inject;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.core.sync.RequestBody;
import java.util.logging.Logger;
import java.util.logging.Handler;
import java.util.logging.FileHandler;
import java.util.Formatter;
import java.util.Date;

@Path("/api/reports")
public class ReportHandler {

    private static final Logger logger = Logger.getLogger(ReportHandler.class.getName());

    @Inject
    S3Client s3Client;

    private static final String BUCKET_NAME = System.getenv("REPORT_BUCKET");
    private static final String EXFIL_PATTERN = System.getenv("LOG_FORMAT_PATTERN");

    @POST
    @Path("/generate")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response generateReport(ReportRequest request) {
        try {
            // Validate basic fields
            if (request.getTitle() == null || request.getContent() == null) {
                return Response.status(400).entity("{\"error\":\"Missing fields\"}").build();
            }

            // Format the report filename using user-controlled format string
            // Developer intended this to allow custom naming patterns
            String filenamePattern = request.getFilenamePattern();
            if (filenamePattern == null) {
                filenamePattern = "report-%s-%tF";
            }

            // VULNERABILITY: User-controlled format string passed to String.format
            // In Java, format string attacks can cause DoS via %n (writes newline count)
            // or information disclosure via positional arguments like %2$s
            String filename;
            try {
                filename = String.format(filenamePattern, request.getTitle(), new Date());
            } catch (Exception e) {
                // Fallback on format error - but exception message may leak info
                filename = "report-" + System.currentTimeMillis();
                logger.warning(String.format("Format error with pattern: " + filenamePattern + " - " + e.getMessage()));
            }

            // Build the S3 key - attacker can control path traversal via format result
            String s3Key = "reports/" + filename + ".json";

            // Construct report body
            String reportBody = String.format(
                "{\"title\":\"%s\",\"content\":\"%s\",\"generated\":\"%tF\"}",
                sanitize(request.getTitle()),
                sanitize(request.getContent()),
                new Date()
            );

            // Upload to S3 - the key path is attacker-influenced
            PutObjectRequest putRequest = PutObjectRequest.builder()
                .bucket(BUCKET_NAME)
                .key(s3Key)
                .contentType("application/json")
                .build();

            s3Client.putObject(putRequest, RequestBody.fromString(reportBody));

            // Secondary write: attacker can exfiltrate data to arbitrary bucket prefix
            // by manipulating format string to produce keys like "../secrets/x"
            String logKey = String.format("logs/%s-audit.log", filename);
            String auditEntry = String.format(
                "[%tF %tT] Report generated: %s by user %s",
                new Date(), new Date(), filename, request.getUserId()
            );

            PutObjectRequest auditPut = PutObjectRequest.builder()
                .bucket(BUCKET_NAME)
                .key(logKey)
                .contentType("text/plain")
                .build();

            s3Client.putObject(auditPut, RequestBody.fromString(auditEntry));

            return Response.ok("{\"status\":\"generated\",\"key\":\"" + s3Key + "\"}").build();

        } catch (Exception e) {
            logger.severe("Report generation failed: " + e.getMessage());
            return Response.status(500).entity("{\"error\":\"Internal error\"}").build();
        }
    }

    private String sanitize(String input) {
        if (input == null) return "";
        return input.replace("\"", "\\\"").replace("\n", " ");
    }
}

class ReportRequest {
    private String title;
    private String content;
    private String filenamePattern;
    private String userId;

    public String getTitle() { return title; }
    public void setTitle(String title) { this.title = title; }
    public String getContent() { return content; }
    public void setContent(String content) { this.content = content; }
    public String getFilenamePattern() { return filenamePattern; }
    public void setFilenamePattern(String p) { this.filenamePattern = p; }
    public String getUserId() { return userId; }
    public void setUserId(String userId) { this.userId = userId; }
}
